class Solution {
  public int missingNumber(int[] arr) {
    int n = arr.length, d = (arr[n - 1] - arr[0]) / n;
    // binary search the first position that is off the progression
    int lo = 0, hi = n - 1;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (arr[mid] == arr[0] + mid * d) lo = mid + 1;
      else hi = mid;
    }
    return arr[0] + lo * d;
  }
}
